const $=q=>document.querySelector(q),app=$('#app'),modal=$('#modal'),t=(de,en)=>s.profile.lang==='de'?de:en,esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=d=>new Date(d+'T12:00:00').toLocaleDateString(s.profile.lang==='de'?'de-DE':'en-GB',{day:'numeric',month:'short',year:'numeric'}),today=()=>localDay(),checked=x=>x?'checked':'',sel=(x,y)=>x===y?'selected':'',num=x=>Number(x).toLocaleString(s.profile.lang==='de'?'de-DE':'en-GB');
