function award(key,type,title,when=today()){if(s.ledger.some(e=>e.key===key))return false;let before=balances(s).level,[xp,dp]=rewards[type];s.ledger.push({key,type,xp,dp,date:when});active(when);let after=balances(s).level;if(after>before){event('level',`Level ${after}`);sound()}toast(`+${xp} XP · +${dp} DP`);return true}
