function avatar(){return `<div class="avatar" style="${s.profile.frame?'box-shadow:0 0 0 3px #c9a45c50':''}">${s.profile.image?`<img src="${safeImage(s.profile.image)}" alt="">`:esc(s.profile.avatar||s.profile.name.slice(0,1).toUpperCase()||'F')}</div>`}
