const moodEmoji=m=>['😞','🙁','😐','🙂','😄'][m]||'○';function journal(){return head('REFLECTION',t('Dein Tagebuch','Your journal'),t('Ein privater Raum für deine Gedanken.','A private space for your thoughts.'),button(t('+ Eintrag','+ Entry'),'journalEdit','','primary'))+`<div class="grid">${card(`<h2>${t('Stimmungsübersicht','Mood overview')}</h2><div class="daygrid">${Array.from({length:7},(_,i)=>shift(today(),i-6)).map(d=>`<div class="day">${d.slice(-2)}<strong>${moodEmoji(s.journal.find(j=>j.date===d)?.mood)}</strong></div>`).join('')}</div><small>${t('Deine Stimmung wird nicht bewertet.','Your mood is never scored.')}</small>`,6)}${card(`<h2>${t('Wochenreflexion','Weekly reflection')}</h2><p class="muted">${t('Was hat gut funktioniert? Was möchtest du ändern?','What worked well? What would you change?')}</p>${button(t('Reflexion schreiben','Write reflection'),'reflection','','small primary')}`,6)}${card(`<div class="flex between"><h2>${t('Einträge','Entries')}</h2>${input('journalSearch','','search','id="journalSearch" placeholder="'+t('Suchen…','Search…')+'" style="max-width:180px"')}</div><div id="journalList">${journalItems('')}</div>`)}</div>`}
