function stats(){let st=streak(s),b=balances(s),start=shift(today(),1-period),days=Array.from({length:Math.min(period,31)},(_,i)=>shift(today(),i-Math.min(period,31)+1)),entries=s.ledger.filter(e=>e.date>=start&&e.date<=today()),cnt=s.tasks.reduce((n,x)=>n+x.done.filter(d=>d>=start&&d<=today()).length,0),f=s.focus.filter(x=>x.date>=start&&x.completed);return head('YOUR PROGRESS',t('Dein Fortschritt','Your progress'),t('Deine Entwicklung auf einen Blick.','Your development at a glance.'))+`<div class="tabs">${[[1,t('Tag','Day')],[7,t('Woche','Week')],[30,t('Monat','Month')],[365,t('Jahr','Year')]].map(([n,l])=>button(l,'period',String(n),period===n?'active':'')).join('')}</div><div class="grid">${[[t('Aufgaben','Tasks'),cnt],[t('Fokusminuten','Focus minutes'),f.reduce((a,x)=>a+x.minutes,0)],[t('Verdiente XP','XP earned'),entries.reduce((a,x)=>a+Math.max(0,x.xp),0)],[t('Verdiente DP','DP earned'),entries.reduce((a,x)=>a+Math.max(0,x.dp),0)]].map(([n,v])=>card(`<div class="eyebrow">${n}</div><div class="big">${num(v)}</div>`,3)).join('')}${card(`<h2>${t('Aufgabenverlauf','Task history')}</h2>${weekChart(days.slice(-14))}<small>${t('Letzte','Last')} ${Math.min(period,14)} ${t('Tage','days')}</small>`,8)}${card(`<h2>${t('Dein Rhythmus','Your rhythm')}</h2><div class="big">${st.count}</div><p class="muted">${t('Längste Serie','Longest streak')}: ${st.best}<br>${t('Aktive Tage insgesamt','Total active days')}: ${st.total}</p><div class="line"></div>Level ${b.level} · ${b.rank}`,4)}${card(`<h2>${t('Zielentwicklung','Goal progress')}</h2>${s.goals.map(g=>`<div class="flex between"><b>${esc(g.name)}</b><small>${goalPct(g)}%</small></div>${progress(goalPct(g))}`).join('')||empty(t('Noch keine Ziele','No goals yet'))}`,6)}${card(`<h2>${t('Erreichte Meilensteine','Milestones reached')}</h2><div class="big">${entries.filter(e=>e.type==='milestone').length}</div><p class="muted">${entries.filter(e=>e.type==='goal').length} ${t('Ziele erreicht','goals achieved')}</p>`,6)}</div>`}
