function editGoal(id=''){let g=by(s.goals,id);open(g?t('Ziel bearbeiten','Edit goal'):t('Neues Ziel','New goal'),nameField(t('Zielname','Goal name'),g?.name)+field(t('Beschreibung','Description'),area('description',g?.description||''))+field(t('Dein Warum','Your why'),area('why',g?.why||''))+`<div class="formgrid">${field(t('Kategorie','Category'),input('category',g?.category||''))}${field(t('Priorität','Priority'),select('priority',[['normal',t('Normal','Normal')],['high',t('Hoch','High')],['low',t('Niedrig','Low')]],g?.priority||'normal'))}${field(t('Startdatum','Start date'),input('start',g?.start||today(),'date','required'))}${field(t('Zieldatum (optional)','Target date (optional)'),input('due',g?.due||'','date'))}</div>`+(g?'':field(t('Meilensteine (eine Zeile pro Schritt)','Milestones (one per line)'),area('milestones'))),f=>{let o={name:f.get('name').trim(),description:f.get('description'),why:f.get('why'),category:f.get('category'),priority:f.get('priority'),start:f.get('start'),due:f.get('due')};if(!o.name||o.due&&o.due<o.start)throw Error(t('Bitte Name und gültiges Datum angeben.','Enter a name and valid dates.'));if(g)Object.assign(g,o);else{s.goals.push({...o,id:uid(),status:'active',milestones:f.get('milestones').split('\n').map(x=>x.trim()).filter(Boolean).map(name=>({id:uid(),name,done:false}))});event('goal',t('Ziel erstellt: ','Goal created: ')+o.name)}})}
